import json

# Analysis: Let me write a function that determines which cells become 7 or 8

def get_neighbors(r, c, rows, cols):
    """Get valid neighbor coordinates"""
    neighbors = []
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            neighbors.append((nr, nc))
    return neighbors

def flood_fill_region(grid, start_r, start_c, rows, cols, include_5=False):
    """Flood fill to find all cells reachable from start position, optionally treating 5 as passable"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    stack = [start_r, start_c]
    result = []

    while stack:
        r, c = stack.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        result.append((r, c))

        for nr, nc in get_neighbors(r, c, rows, cols):
            if (nr, nc) not in visited:
                if not include_5:
                    if grid[nr][nc] != 5:  # Only 0s passable
                        stack.append((nr, nc))
                else:
                    stack.append((nr, nc))  # 5s also passable

    return result

def regions_by_reachability(grid, color, rows, cols):
    """Determine if a cell becomes color based on reachability from boundaries"""
    # Color 7: can reach LEFT or TOP boundary
    # Color 8: can reach RIGHT or BOTTOM boundary

    result = {}

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5:
                result[(r,c)] = 5  # 5s stay 5
                continue

            # Check reachability to settings
            can_reach_top = False
            can_reach_left = False
            can_reach_bottom = False
            can_reach_right = False

            # Flood fill only through 0s, check if we hit each boundary
            stack = [(r, c)]
            seen = {(r, c)}
            while stack:
                cr, cc = stack.pop()

                if cr == 0:
                    can_reach_top = True
                if cc == 0:
                    can_reach_left = True
                if cr == rows - 1:
                    can_reach_bottom = True
                if cc == cols - 1:
                    can_reach_right = True

                for nr, nc in get_neighbors(cr, cc, rows, cols):
                    if (nr, nc) not in seen and grid[nr][nc] != 5:
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            # Based on reachability, assign color
            if can_reach_top or can_reach_left:
                result[(r,c)] = 7
            elif can_reach_right or can_reach_bottom:
                result[(r,c)] = 8
